<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/DestinationImporter.php';
require dirname(__DIR__).'/app/DestinationAdminService.php';
function admin_check(bool $ok,string $message): void { if(!$ok) throw new RuntimeException($message); }
$pdo=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$pdo->exec(file_get_contents(dirname(__DIR__).'/database/destinations.sqlite.sql'));
$pdo->exec(file_get_contents(dirname(__DIR__).'/database/migrations/006-poi-experience-links.sqlite.sql'));
$root=dirname(__DIR__,2);$catalog=json_decode(file_get_contents($root.'/content/destinos-dinamicos.json'),true,512,JSON_THROW_ON_ERROR);$options=json_decode(file_get_contents(dirname(__DIR__).'/app/contact-options.json'),true,512,JSON_THROW_ON_ERROR);
DestinationImporter::import($pdo,$catalog,$options);$admin=new DestinationAdminService($pdo);
$all=$admin->all();admin_check(count($all)===21,'Admin lists the imported 21 destinations');
$jericoId=(int)$pdo->query("SELECT id FROM destinations WHERE slug='jerico'")->fetchColumn();$jerico=$admin->find($jericoId);
admin_check($jerico!==null&&count($jerico['places'])===8,'Existing destination loads all places and activities');
$input=['id'=>$jericoId,'slug'=>'jerico','destination_type'=>'municipality','country_code'=>'CO','department'=>'Antioquia','subregion'=>'Suroeste','latitude'=>'5.79','longitude'=>'-75.78','publication_status'=>'published','display_order'=>'1','translations'=>[],'history'=>[],'reasons'=>[],'places'=>[],'sources'=>[],'hero_asset_id'=>'0','history_asset_id'=>'0'];
foreach(['es','en','pt-BR'] as $locale){$t=$jerico['translations'][$locale];$input['translations'][$locale]=['display_name'=>$t['display_name'],'eyebrow'=>$t['eyebrow'],'headline'=>$t['headline'],'intro'=>$t['intro'],'meta_description'=>$t['meta_description']];$input['history'][$locale]=implode("\n",$jerico['history'][$locale]);$input['reasons'][$locale]=implode("\n",$jerico['reasons'][$locale]);$input['sources'][$locale]='';}
foreach($jerico['sources']['es'] as $source)$input['sources']['es'].=$source['section_key'].'|'.$source['source_label'].'|'.$source['source_url']."\n";
foreach($jerico['places'] as $i=>$place){$input['places'][$i]=['id'=>$place['id'],'slug'=>$place['slug'],'type'=>$place['type'],'latitude'=>$place['latitude']??'','longitude'=>$place['longitude']??'','publication_status'=>$place['publication_status'],'media_asset_id'=>$place['media_asset_id']??0,'translations'=>[]];foreach(['es','en','pt-BR'] as $locale){$p=$place['translations'][$locale];$input['places'][$i]['translations'][$locale]=['name'=>$p['name'],'description'=>$p['description'],'map_url'=>$p['map_url'],'external_url'=>$p['external_url'],'external_label'=>$p['external_label']];}}
$input['translations']['es']['headline']='Jericó editable';$retainedPlaceId=$jerico['places'][1]['id'];$input['places']=array_values(array_slice($input['places'],1));$input['places'][0]['translations']['es']['name']='Centro histórico editado';
$saved=$admin->save($input,[],[],sys_get_temp_dir());admin_check($saved===$jericoId,'Edit retains the internal destination ID');
$edited=$admin->find($jericoId);admin_check($edited['translations']['es']['headline']==='Jericó editable','Spanish editorial text is saved');admin_check($edited['places'][0]['translations']['es']['name']==='Centro histórico editado','POI translation is saved');admin_check($edited['places'][0]['id']===$retainedPlaceId,'Reordering and editing a POI keeps its numeric identity');admin_check(count($edited['places'])===8&&$edited['places'][7]['publication_status']==='archived','Omitted places and activities are retained as hidden records, never physically removed');admin_check((int)$pdo->query('SELECT COUNT(*) FROM destinations')->fetchColumn()===21,'Editing does not duplicate the destination');
$draft=['slug'=>'','destination_type'=>'municipality','country_code'=>'CO','department'=>'Antioquia','subregion'=>'','publication_status'=>'draft','display_order'=>'0','translations'=>[],'history'=>[],'reasons'=>[],'places'=>[],'sources'=>[],'hero_asset_id'=>'0','history_asset_id'=>'0'];
foreach(['es','en','pt-BR'] as $locale){$draft['translations'][$locale]=['display_name'=>'','eyebrow'=>'','headline'=>'','intro'=>'','meta_description'=>''];$draft['history'][$locale]='';$draft['reasons'][$locale]='';$draft['sources'][$locale]='';}
$draft['translations']['es']['display_name']='Prueba de municipio';
$draft['internal_research_json']=json_encode(['schema_version'=>1,'researched_at'=>'2026-10-14','positioning'=>'Prueba interna.','competitors'=>[['name'=>'Mapa','url'=>'https://example.org/map']],'potential_allies'=>[['name'=>'Entidad local','website_url'=>'https://example.org']],'business_prospects'=>[['name'=>'Negocio de prueba','source_url'=>'https://example.org/registry']],'acquisition_strategies'=>[['first_action'=>'Conversación presencial']],'sources'=>[['url'=>'https://example.org/source']],'notes'=>['No publicar ni contactar automáticamente.']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
$draft['internal_research_json']=json_encode(['schema_version'=>1,'researched_at'=>'2026-10-14','positioning'=>'Prueba interna.','competitors'=>[['name'=>'Mapa','url'=>'https://example.org/map']],'potential_allies'=>[['name'=>'Entidad local','website_url'=>'https://example.org']],'business_prospects'=>[['name'=>'Negocio de prueba','source_url'=>'https://example.org/registry']],'acquisition_strategies'=>[['first_action'=>'Conversación presencial']],'sources'=>[['url'=>'https://example.org/source']],'notes'=>['No publicar ni contactar automáticamente.']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
$draft['sources']['es']='https://sonson-antioquia.gov.co/';
$draft['places'][]=['slug'=>'','publication_status'=>'draft','media_asset_id'=>'0','translations'=>['es'=>['name'=>'Plaza principal','description'=>'Centro del municipio.','map_url'=>''],'en'=>['name'=>'Main square','description'=>'Town centre.','map_url'=>''],'pt-BR'=>['name'=>'Praça principal','description'=>'Centro do município.','map_url'=>'']]];
$orphanImageRejected=false;try{$admin->save($draft,[],['error'=>[1=>UPLOAD_ERR_OK]],sys_get_temp_dir());}catch(RuntimeException $e){$orphanImageRejected=true;}admin_check($orphanImageRejected,'Image upload without a named attraction is rejected instead of silently ignored');
$newId=$admin->save($draft,[],[] ,sys_get_temp_dir());$new=$admin->find($newId);admin_check($newId>0&&$new['publication_status']==='draft','Draft destination can be created with an assigned ID');admin_check($new['slug']==='prueba-de-municipio','Destination URL identifier is derived from its Spanish name');admin_check($new['places'][0]['slug']==='plaza-principal'&&$new['places'][0]['publication_status']==='draft','New attractions remain unpublished by default');admin_check(str_contains($new['places'][0]['translations']['es']['map_url'],'google.com/maps/search/'),'Map search URL is generated without requiring a URL field');admin_check($new['sources']['es'][0]['source_label']==='sonson-antioquia.gov.co','A plain source URL is saved with an automatic label');
$research=json_decode($new['internal_research_json'],true,512,JSON_THROW_ON_ERROR);admin_check($research['competitors'][0]['name']==='Mapa'&&$research['notes'][0]==='No publicar ni contactar automáticamente.','Internal market research, prospects and acquisition notes persist in the draft');
$badResearch=$draft;$badResearch['id']=$newId;$badResearch['internal_research_json']='{"schema_version":1,"competitors":[{"url":"http://insecure.example"}]}';$badResearchRejected=false;try{$admin->save($badResearch,[],[],sys_get_temp_dir());}catch(RuntimeException $e){$badResearchRejected=true;}admin_check($badResearchRejected,'Non-HTTPS research links are rejected');
$draft['id']=$newId;$draft['publication_status']='published';$rejected=false;try{$admin->save($draft,[],[],sys_get_temp_dir());}catch(RuntimeException $e){$rejected=true;}admin_check($rejected,'Incomplete destination cannot be published');
$category=(string)$pdo->query('SELECT code FROM service_categories LIMIT 1')->fetchColumn();$business=$pdo->prepare('INSERT INTO businesses(public_id,destination_id,category_code,slug) VALUES(?,?,?,?)');$business->execute(['test-public-id',$newId,$category,'negocio-prueba']);
$blocked=false;try{$admin->delete($newId);}catch(RuntimeException $e){$blocked=true;}admin_check($blocked,'Destination deletion is blocked while a business refers to it');
$admin->archive($newId);admin_check($admin->find($newId)['publication_status']==='archived','Archive preserves the destination record');$pdo->prepare('DELETE FROM businesses WHERE destination_id=?')->execute([$newId]);$admin->delete($newId);admin_check($admin->find($newId)===null,'Unreferenced destination can be deleted');
echo "OK: destination admin listing, ID-based editing, draft creation, publish validation, archive and safe deletion.\n";
